"use client";

import { useEffect, useRef } from "react";
import gsap from "gsap";

interface WorkOverlayProps {
  isOpen: boolean;
  onClose?: () => void;
  children?: React.ReactNode;
}

export default function WorkOverlay({ isOpen, onClose, children }: WorkOverlayProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const isMountedRef = useRef(false);
  const onCloseRef = useRef(onClose);

  useEffect(() => {
    onCloseRef.current = onClose;
  });

  useEffect(() => {
    if (!containerRef.current) return;

    if (!isMountedRef.current) {
      isMountedRef.current = true;
      gsap.set(containerRef.current, {
        yPercent: isOpen ? 0 : 100,
        autoAlpha: isOpen ? 1 : 0,
        display: isOpen ? "block" : "none",
      });
      if (!isOpen) return;
    }

    if (isOpen) {
      document.body.style.overflow = "hidden";
      gsap.killTweensOf(containerRef.current);
      gsap.set(containerRef.current, { display: "block", autoAlpha: 1 });
      gsap.fromTo(
        containerRef.current,
        { yPercent: 100 },
        {
          yPercent: 0,
          duration: 0.75,
          ease: "power4.out",
        }
      );

      const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === "Escape") {
          onCloseRef.current?.();
        }
      };

      window.addEventListener("keydown", handleKeyDown);

      return () => {
        document.body.style.overflow = "";
        window.removeEventListener("keydown", handleKeyDown);
      };
    } else {
      document.body.style.overflow = "";
      gsap.killTweensOf(containerRef.current);
      gsap.to(containerRef.current, {
        yPercent: 100,
        duration: 0.5,
        ease: "power3.in",
        onComplete: () => {
          if (containerRef.current) {
            gsap.set(containerRef.current, { autoAlpha: 0, display: "none" });
          }
        },
      });
    }
  }, [isOpen]);

  return (
    <div
      ref={containerRef}
      id="work-overlay"
      aria-hidden={!isOpen}
      className="fixed left-0 right-0 bottom-0 top-16 sm:top-20 z-40 bg-white overflow-y-auto overscroll-contain will-change-transform pointer-events-auto"
    >
      {children}
    </div>
  );
}
